"use client";

import Link from "next/link";
import { useCallback, useEffect, useRef, useState } from "react";
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BadgeCheck, Ban, Check, CheckCircle2, ChevronDown, ChevronRight, CircleAlert, Clock3, Copy, ExternalLink, FileCheck2, FileDown, FileText, Info, LoaderCircle, LockKeyhole, MessageSquareText, MoreHorizontal, MousePointer2, Play, RefreshCw, ShieldAlert, ShieldCheck, Stamp, Timer, TriangleAlert, X } from "lucide-react";
import { answerCase, cancelRun, checkStatus, connectCaseEvents, discoverRoute, downloadEvidence, finishMockRun, generateDraft, getCase, getClock, getRunOutcome, isMock, planCase, prepareNext, previewPrefill, recordSubmitted, saveDraft, startPrefill } from "@/lib/api";
import type { CaseRecord, DemoClock, Draft, EscalationPack, Language, ReviewPacket, Step } from "@/lib/types";
import { usePrefs } from "@/components/app-shell";

type Tab = "plan" | "draft" | "agent" | "timeline";
type FeedEntry = { at: string; message: string; kind: "start" | "fill" | "review" | "warn" | "fail" };

export function CasePage({ id }: { id: string }) {
  const { language, t } = usePrefs();
  const runActive = useRef(false);
  const currentRunId = useRef<string | null>(null);
  const [record, setRecord] = useState<CaseRecord | null>(null); const [clock, setClock] = useState<DemoClock | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const [activeTab, setActiveTab] = useState<Tab>("plan"); const [selectedOrdinal, setSelectedOrdinal] = useState(1); const [answers, setAnswers] = useState<Record<string, string | boolean>>({}); const [answering, setAnswering] = useState(false);
  const [modal, setModal] = useState<"approve" | "submitted" | null>(null); const [preview, setPreview] = useState<Awaited<ReturnType<typeof previewPrefill>> | null>(null); const [portal, setPortal] = useState<"sandbox" | "live">("sandbox"); const [approved, setApproved] = useState(false); const [working, setWorking] = useState(false); const [draftBody, setDraftBody] = useState(""); const [draftSubject, setDraftSubject] = useState(""); const [saving, setSaving] = useState(false); const [savedLabel, setSavedLabel] = useState(""); const [feed, setFeed] = useState<FeedEntry[]>([]); const [isRunning, setIsRunning] = useState(false); const [streamingUrl, setStreamingUrl] = useState<string | null>(null); const [packet, setPacket] = useState<ReviewPacket | null>(null); const [ack, setAck] = useState(""); const [ackDate, setAckDate] = useState(""); const [ackError, setAckError] = useState(""); const [pack, setPack] = useState<EscalationPack | null>(null); const [checkText, setCheckText] = useState(""); const [stampOpen, setStampOpen] = useState<number | null>(null); const [routeLoading, setRouteLoading] = useState(false); const [confirmStop, setConfirmStop] = useState(false); const [safetyAlert, setSafetyAlert] = useState<{ evidence: string; reason: string } | null>(null);

  const refresh = useCallback(async () => { try { setRecord(await getCase(id)); setError(""); } catch (issue) { setError(issue instanceof Error ? issue.message : "We couldn’t open this case."); } }, [id]);
  useEffect(() => { void Promise.all([getCase(id), getClock()]).then(([nextCase, nextClock]) => { setRecord(nextCase); setClock(nextClock); setAnswers({ "prior_contact.contacted_company": true, "prior_contact.date": "2026-10-02", "prior_contact.got_reply": false }); setLoading(false); }).catch((issue: unknown) => { setError(issue instanceof Error ? issue.message : "We couldn’t open this case."); setLoading(false); }); }, [id]);
  useEffect(() => { const onClock = (event: Event) => { const custom = event as CustomEvent<DemoClock>; setClock(custom.detail); void refresh(); }; window.addEventListener("sunwai:clock", onClock); return () => window.removeEventListener("sunwai:clock", onClock); }, [refresh]);
  useEffect(() => connectCaseEvents(id, (event) => {
    if (["case_updated", "run_completed", "draft_ready", "status_checked", "step_due", "rule_changed"].includes(event.type)) void refresh();
    if (event.type === "run_completed") { runActive.current = false; currentRunId.current = null; setIsRunning(false); }
    if (event.type === "streaming_url") setStreamingUrl(String(event.payload.streaming_url || ""));
    if (event.type === "agent_event") { const payload = event.payload; if (payload.tf_type !== "HEARTBEAT") setFeed((items) => [...items.slice(-199), { at: new Date(event.at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }), message: String(payload.message || "Working on the complaint form"), kind: "fill" }]); }
    if (event.type === "review_ready") { runActive.current = false; setIsRunning(false); const packet = event.payload.review_packet as ReviewPacket; setPacket(packet); setActiveTab("agent"); }
    if (event.type === "blocker") { runActive.current = false; setIsRunning(false); setActiveTab("agent"); setFeed((items) => [...items, { at: "Now", message: String(event.payload.message || "The agent needs you to continue on the portal."), kind: "warn" }]); }
    if (event.type === "safety_flagged") { runActive.current = false; setIsRunning(false); setSafetyAlert({ reason: String(event.payload.reason || "The agent may have tried a final action."), evidence: String(event.payload.evidence || "Please inspect the portal before doing anything else.") }); setActiveTab("agent"); }
    if (event.type === "run_failed") { runActive.current = false; setIsRunning(false); setFeed((items) => [...items, { at: "Now", message: String(event.payload.message || "This run could not finish."), kind: "fail" }]); setActiveTab("agent"); }
  }), [id, refresh]);
  useEffect(() => { const selected = record?.steps.find((step) => step.ordinal === selectedOrdinal); if (selected?.draft) { setDraftBody(selected.draft.body); setDraftSubject(selected.draft.subject); } else { setDraftBody(""); setDraftSubject(""); } }, [record, selectedOrdinal]);

  const currentStep = record?.steps.find((step) => step.ordinal === selectedOrdinal) || record?.steps[0] || null;
  const displayDate = (value: string | null | undefined) => { if (!value) return "—"; return new Intl.DateTimeFormat(language === "hi" ? "hi-IN" : "en-IN", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Kolkata" }).format(new Date(`${value}T12:00:00+05:30`)); };
  const formatMoney = (amount: number | null) => amount == null ? "Not provided" : `₹${new Intl.NumberFormat("en-IN").format(amount)}`;
  const localized = (step: Step, field: "action" | "why") => language === "hi" ? step[`${field}_hi`] : step[field];
  const factsDone = Boolean(record && record.steps.length > 0);

  const handlePlan = async () => { if (!record) return; setAnswering(true); try { const answered = await answerCase(record.id, { "prior_contact.contacted_company": answers["prior_contact.contacted_company"] ?? true, "prior_contact.date": answers["prior_contact.date"] || "2026-10-02", "prior_contact.got_reply": answers["prior_contact.got_reply"] ?? false }); const planned = await planCase(answered.id); setRecord(planned); setSelectedOrdinal(1); setActiveTab("plan"); } catch (issue) { setError(issue instanceof Error ? issue.message : "We couldn’t make the plan."); } finally { setAnswering(false); } };
  const handleDraft = async () => { if (!currentStep || !record) return; setWorking(true); setError(""); try { const draft = await generateDraft(record.id, currentStep.ordinal); setRecord(await getCase(record.id)); setDraftBody(draft.body); setDraftSubject(draft.subject); setActiveTab("draft"); } catch (issue) { setError(issue instanceof Error ? issue.message : "We couldn’t create the draft."); } finally { setWorking(false); } };
  const handleSaveDraft = async () => { if (!record || !currentStep) return; setSaving(true); setSavedLabel(""); try { await saveDraft(record.id, currentStep.ordinal, { subject: draftSubject, body: draftBody }); setRecord(await getCase(record.id)); setSavedLabel(t("saved")); window.setTimeout(() => setSavedLabel(""), 2500); } catch (issue) { setError(issue instanceof Error ? issue.message : "We couldn’t save the draft."); } finally { setSaving(false); } };
  const openApprove = async () => { if (!record || !currentStep) return; if (!currentStep.draft) { await handleDraft(); return; } setWorking(true); try { setPreview(await previewPrefill(record.id, currentStep.ordinal, portal)); setApproved(false); setModal("approve"); } catch (issue) { setError(issue instanceof Error ? issue.message : "We couldn’t prepare a preview."); } finally { setWorking(false); } };
  const runPrefill = async () => {
    if (!record || !currentStep || !approved) return; setWorking(true); setModal(null); setPacket(null); setStreamingUrl(null); setSafetyAlert(null); setActiveTab("agent"); runActive.current = true; setIsRunning(true); setFeed([{ at: "Now", message: "Opening the complaint form", kind: "start" }]);
    try {
      const run = await startPrefill(record.id, currentStep.ordinal, portal); currentRunId.current = run.run_id; await refresh();
      if (isMock()) {
        const events = ["Checking the demo portal and its form fields", "Choosing category: UPI / payment", `Entering transaction date ${record.case_json.incident_date || "30/09/2026"}`, `Adding reference ${record.case_json.reference_numbers[0] || "XXXX2841"}`, `Adding amount ${formatMoney(record.case_json.amount_inr)}`, "Pasting your complaint draft", "Reviewing the details that were filled", "Stopping before the final Submit action"];
        for (const [index, message] of events.entries()) { await new Promise((resolve) => window.setTimeout(resolve, 780)); if (!runActive.current && index > 0) break; setFeed((items) => [...items.slice(-199), { at: `${index + 1}s`, message, kind: index === events.length - 1 ? "review" : "fill" }]); }
        await new Promise((resolve) => window.setTimeout(resolve, 350));
        if (runActive.current) { const updated = await finishMockRun(record.id, currentStep.ordinal, getRunOutcome(), portal); setRecord(updated); const step = updated.steps.find((entry) => entry.ordinal === currentStep.ordinal); setPacket(step?.review_packet || null); if (step?.latest_run?.status === "failed") setFeed((items) => [...items, { at: "Now", message: step.latest_run?.error?.message || t("errorTitle"), kind: "fail" }]); }
        runActive.current = false; setIsRunning(false);
      }
    } catch (issue) { runActive.current = false; setIsRunning(false); setError(issue instanceof Error ? issue.message : t("errorTitle")); }
    finally { setWorking(false); }
  };
  const stopRun = async () => { if (!record || !currentStep) return; runActive.current = false; setConfirmStop(false); setIsRunning(false); try { await cancelRun(currentRunId.current); currentRunId.current = null; } catch (issue) { setError(issue instanceof Error ? issue.message : "The run could not be stopped on the server."); } setFeed((items) => [...items, { at: "Now", message: "Run stopped by you. You can continue on the portal or retry.", kind: "warn" }]); await refresh(); };
  const openSubmit = () => { setAck(""); setAckError(""); setAckDate(clock?.today || "2026-10-24"); setModal("submitted"); };
  const submitRecord = async () => { if (!record || !currentStep) return; if (ack.trim().length < 3) { setAckError("Enter the acknowledgement number from the portal confirmation."); return; } if (!ackDate || (clock?.today && ackDate > clock.today)) { setAckError("Choose the date you filed. It can’t be after the demo date."); return; } setWorking(true); try { const updated = await recordSubmitted(record.id, currentStep.ordinal, ack, ackDate); setRecord(updated); setModal(null); setPacket(null); setActiveTab("timeline"); } catch (issue) { setAckError(issue instanceof Error ? issue.message : "We couldn’t record this filing."); } finally { setWorking(false); } };
  const handlePrepareNext = async (step: Step) => { if (!record) return; setWorking(true); try { const prepared = await prepareNext(record.id, step.ordinal); setPack(prepared); const updated = await getCase(record.id); setRecord(updated); if (prepared.next_forum_id) setSelectedOrdinal(step.ordinal + 1); if (prepared.draft) { setDraftSubject(prepared.draft.subject); setDraftBody(prepared.draft.body); } setActiveTab("draft"); } catch (issue) { setError(issue instanceof Error ? issue.message : "We couldn’t prepare the next filing."); } finally { setWorking(false); } };
  const handleStatus = async (step: Step) => { if (!record) return; setCheckText("Checking the portal status…"); try { const result = await checkStatus(record.id, step.ordinal); if (result.case) setRecord(result.case); else await refresh(); setCheckText("Status checked · received and under review"); } catch (issue) { setCheckText(issue instanceof Error ? issue.message : "Couldn’t check status."); } };
  const handleRoute = async (step: Step) => { if (!record) return; setRouteLoading(true); try { const updated = await discoverRoute(record.id, step.ordinal); if ("steps" in updated) setRecord(updated); else await refresh(); } catch (issue) { setError(issue instanceof Error ? issue.message : "We couldn’t find the route."); } finally { setRouteLoading(false); } };
  const copyDraft = async () => { await navigator.clipboard?.writeText(`${draftSubject}\n\n${draftBody}`); setSavedLabel("Copied"); window.setTimeout(() => setSavedLabel(""), 2000); };

  if (loading) return <main className="case-loading"><span className="skeleton-line w-36"/><span className="skeleton-line w-64"/><div className="skeleton-sheet"/><p>Opening your case file…</p></main>;
  if (!record) return <main className="case-error"><div className="error-icon"><CircleAlert size={24}/></div><h1>We couldn’t open this case</h1><p>{error || "This case may have been removed from the demo list."}</p><Link className="button button-primary" href="/cases">{t("navCases")} <ArrowRight size={16}/></Link></main>;

  return <main className="case-workspace">
    <div className="case-breadcrumb"><Link href="/cases">{t("navCases")}</Link><ChevronRight size={13}/><span>{record.case_json.counterparty.name || "New case"}</span><span className="breadcrumb-id">{record.id}</span></div>
    {error && <div className="case-banner error-banner" role="alert"><CircleAlert size={16}/><span>{error}</span><button onClick={() => setError("")} aria-label={t("close")}><X size={15}/></button></div>}
    {!factsDone ? <>
      <header className="case-title-row"><div><span className="eyebrow">CASE FILE · {record.id}</span><h1>{t("factsTitle")}</h1><p>{t("factsIntro")}</p></div><span className="state-pill state-intake">INTAKE COMPLETE</span></header>
      <section className="facts-layout">
        <div className="facts-main sheet"><div className="facts-summary"><div className="summary-label"><FileText size={16}/><span>YOUR STORY</span></div><p>{record.case_json.summary}</p></div>
          <div className="facts-grid"><Fact label={t("company")} value={record.case_json.counterparty.name || "Not sure yet"}/><Fact label={t("amount")} value={formatMoney(record.case_json.amount_inr)}/><Fact label={t("incidentDate")} value={displayDate(record.case_json.incident_date)}/><Fact label={t("reference")} value={record.case_json.reference_numbers.join(" · ")} masked/></div>
          {record.case_json.pii_flags.includes("sensitive_data_in_input") && <div className="privacy-notice"><LockKeyhole size={16}/><span>{t("piiNotice")}</span></div>}
        </div>
        <div className="questions-card sheet"><div className="card-topline"><span className="eyebrow">{t("quickDetails")}</span><span className="question-count">1–3 of 3</span></div><h2>{t("timingQuestion")}</h2>
          <fieldset className="question-field"><legend>{t("contacted")}</legend><div className="segmented"><button type="button" className={answers["prior_contact.contacted_company"] === true ? "selected" : ""} onClick={() => setAnswers({ ...answers, "prior_contact.contacted_company": true })}>{t("yes")}</button><button type="button" className={answers["prior_contact.contacted_company"] === false ? "selected" : ""} onClick={() => setAnswers({ ...answers, "prior_contact.contacted_company": false })}>{t("no")}</button></div></fieldset>
          <label className="question-field"><span>{t("contactDate")}</span><input type="date" value={String(answers["prior_contact.date"] || "2026-10-02")} max={clock?.today || "2026-10-24"} onChange={(event) => setAnswers({ ...answers, "prior_contact.date": event.target.value })}/></label>
          <fieldset className="question-field"><legend>{t("replied")}</legend><div className="segmented"><button type="button" className={answers["prior_contact.got_reply"] === true ? "selected" : ""} onClick={() => setAnswers({ ...answers, "prior_contact.got_reply": true })}>{t("yes")}</button><button type="button" className={answers["prior_contact.got_reply"] === false ? "selected" : ""} onClick={() => setAnswers({ ...answers, "prior_contact.got_reply": false })}>{t("no")}</button></div></fieldset>
          <p className="question-help"><Info size={14}/> {t("timingHint")}</p><button className="button button-primary button-full" onClick={() => void handlePlan()} disabled={answering}>{answering ? <><LoaderCircle className="spin" size={16}/> Making your plan…</> : <>{t("makePlan")} <ArrowRight size={16}/></>}</button>
        </div>
      </section>
    </> : <>
      <header className="case-title-row case-heading"><div><div className="case-title-eyebrow"><span className="case-file-index">{record.id}</span><span className="eyebrow">{t("casePlanEyebrow")}</span></div><h1>{record.case_json.counterparty.name || "Your complaint"}<span className="title-dot">.</span></h1><p className="case-subtitle">{record.case_json.summary}</p></div><div className="case-title-meta"><span className={`state-pill state-${record.state.toLowerCase()}`}>{stateLabel(record.state, t)}</span><div className="deadline-block"><span>{t("nextDeadline")}</span><strong>{displayDate(record.steps.find((step) => step.status === "open" || step.status === "locked")?.closes_at || record.steps[1]?.opens_at)}</strong></div></div></header>
      {(record.warnings.length > 0 || record.steps.some((step) => step.rule?.freshness === "seed")) && <div className="case-warning"><TriangleAlert size={16}/><div><strong>Dates in this demo use stored rule data.</strong><span>Check each official source before you file.</span></div><button type="button" aria-label="Dismiss warning"><X size={15}/></button></div>}
      {record.steps[1]?.rule?.freshness === "seed" && <div className="rule-change-banner"><div className="rule-flip" aria-hidden="true"><span>OLD</span><b>1 year</b></div><div className="rule-change-copy"><span className="eyebrow">{t("ruleUpdateDemo")}</span><h2>{t("ruleChanged")}</h2><p><span>Before 1 July 2026: <s>1 year</s></span><ArrowRight size={15}/><strong>Now: 90 days</strong></p><small>{t("whyMatters")}: this case’s demo deadline is <b>{displayDate(record.steps[1].closes_at)}</b>. Verify the current rule before filing.</small></div><button className="rule-stamp" onClick={() => setStampOpen(stampOpen === 2 ? null : 2)}><BadgeCheck size={17}/><span>STORED<br/>DEMO RULE</span></button></div>}
      <div className="workspace-tabs" role="tablist" aria-label="Case workspace">{(["plan", "draft", "agent", "timeline"] as Tab[]).map((tab) => <button key={tab} className={activeTab === tab ? "active" : ""} role="tab" aria-selected={activeTab === tab} onClick={() => setActiveTab(tab)}><TabIcon tab={tab}/>{t(tab)}{tab === "agent" && (isRunning || packet) && <i className="tab-activity"/>}</button>)}</div>
      <div className={`workspace-grid ${activeTab !== "plan" ? "focused-work" : ""}`}>
        <aside className={`ladder-column ${activeTab !== "plan" ? "mobile-hidden" : ""}`}><div className="ladder-heading"><div><span className="eyebrow">{t("escalationRoute")}</span><h2>{t("nextSteps")}</h2></div><button className="icon-button" aria-label="More options"><MoreHorizontal size={19}/></button></div>
          <div className="ladder-visual" aria-label="A visual map of your complaint route"><div className="ladder-canvas-stair"/><div className="ladder-file-shape"><span className="file-tab-mini">CASE</span><span className="file-lines-mini"><i/><i/><i/></span><span className="file-stamp-mini">SUNWAI<br/>FILE</span></div><div className="ladder-route-caption"><span className="live-dot"/>THE WAY FORWARD</div><span className="ladder-visual-label label-1">Company</span><span className="ladder-visual-label label-2">RBI</span><span className="ladder-visual-label label-3">Consumer help</span></div>
          <ol className="ladder-list">{record.steps.map((step) => <li key={step.ordinal} className={`ladder-item ${step.status === "open" || step.status === "due" || step.status === "review_ready" ? "is-current" : ""} ${selectedOrdinal === step.ordinal ? "is-selected" : ""}`}><button className="step-card" onClick={() => { setSelectedOrdinal(step.ordinal); if (activeTab !== "plan") setActiveTab("plan"); }} aria-current={selectedOrdinal === step.ordinal ? "step" : undefined}><span className={`step-index index-${step.status}`}><span>{String(step.ordinal).padStart(2, "0")}</span><i/></span><span className="step-info"><span className="step-status">{statusLabel(step.status, t)}</span><strong>{language === "hi" ? step.forum.name_hi : step.forum.name}</strong><span className="step-action-label">{localized(step, "action")}</span><span className="step-date-row">{step.opens_at && <span>{step.status === "locked" ? `${t("opens")} ${displayDate(step.opens_at)}` : displayDate(step.opens_at)}</span>}{step.closes_at && <span className="step-close">{t("lastDay")} {displayDate(step.closes_at)}</span>}{step.opens_when && <span>{step.opens_when}</span>}</span></span><span className={`status-pill status-${step.status}`}>{statusIcon(step.status)}</span></button><div className="step-proof-row"><button className={`proof-chip proof-${step.rule?.freshness || "seed"}`} onClick={() => setStampOpen(stampOpen === step.ordinal ? null : step.ordinal)}><span className="proof-double"><BadgeCheck size={12}/></span><span>{step.rule?.freshness === "live" ? t("verified") : t("stored")}</span><span className="proof-domain">{step.rule?.source_domain || "source"}</span><ChevronDown size={11}/></button>{step.needs_verification && <span className="verification-needed"><TriangleAlert size={12}/> {t("needsCheck")}</span>}{stampOpen === step.ordinal && <div className="proof-popover"><span className="proof-popover-kicker">{step.rule?.source_title}</span><p>“{step.rule?.evidence_snippet}”</p><span>Checked {step.rule?.fetched_at ? new Date(step.rule.fetched_at).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }) : "in the demo"}</span><a href={step.rule?.source_url || step.forum.official_url || "#"} target="_blank" rel="noreferrer">Open source <ArrowUpRight size={12}/></a></div>}</div>{step.status === "waiting" && step.due_at && <div className="waiting-progress"><div className="waiting-progress-head"><span><Clock3 size={13}/>{t("waiting")}</span><b>{displayDate(step.due_at)}</b></div><div className="progress-track"><i style={{ width: `${Math.min(88, Math.max(10, ((clock?.offset_days || 0) / 30) * 100))}%` }}/></div></div>}</li>)}</ol>
          <div className="ladder-assurance"><ShieldCheck size={15}/><span>Every date has a source. Every decision stays yours.</span></div>
        </aside>

        <section className={`work-column ${activeTab === "plan" ? "mobile-hidden" : ""}`}>
          {activeTab === "plan" && currentStep && <StepWork step={currentStep} record={record} language={language} t={t} onWrite={() => void handleDraft()} onPrefill={() => void openApprove()} onRoute={() => void handleRoute(currentStep)} routeLoading={routeLoading} onStatus={() => void handleStatus(currentStep)} checkText={checkText} onPrepare={() => void handlePrepareNext(currentStep)} onPacket={() => { setPacket(currentStep.review_packet); setActiveTab("agent"); }} working={working}/>} 
          {activeTab === "draft" && currentStep && <div className="work-panel"><div className="panel-topline"><div><span className="eyebrow">STEP {currentStep.ordinal} · COMPLAINT LETTER</span><h2>{t("draftTitle")}</h2></div><span className={currentStep.draft ? "draft-state saved-state" : "draft-state"}>{currentStep.draft ? <><Check size={12}/>{savedLabel || t("saved")}</> : "NOT STARTED"}</span></div>
            {pack && <div className="escalation-pack"><div className="pack-icon"><FileCheck2 size={18}/></div><div className="pack-content"><div className="pack-heading"><strong>{pack.recommendation === "needs_user_input" ? language === "hi" ? "और जानकारी चाहिए" : "More information needed" : t("nextFilingPrepared")}</strong><span className="pack-recommendation">{pack.recommendation === "needs_user_input" ? "NEEDS INPUT" : pack.recommendation.toUpperCase()}</span></div><p>{pack.reasoning}</p>{pack.filing_deadline && <div className="pack-deadline"><span>{t("deadline")}</span><b>{displayDate(pack.filing_deadline)}</b></div>}{pack.evidence_pack_checklist.length > 0 && <><strong className="checklist-title">{t("evidenceChecklist")}</strong>{pack.evidence_pack_checklist.map((entry) => <label className="checklist-line" key={entry}><input type="checkbox"/><span>{entry}</span></label>)}</>}{pack.needs_verification && <p className="pack-warning"><TriangleAlert size={14}/> Check current eligibility and deadline on the official site.</p>}</div></div>}
            {!currentStep.draft ? <div className="draft-empty"><div className="draft-empty-icon"><FileText size={25}/></div><h3>{t("startFactualDraft")}</h3><p>{t("draftHelp")}</p><button className="button button-secondary" onClick={() => void handleDraft()} disabled={working}>{working ? <LoaderCircle className="spin" size={16}/> : <FileText size={16}/>} {t("writeComplaint")}</button></div> : <DraftEditor subject={draftSubject} body={draftBody} onSubject={setDraftSubject} onBody={setDraftBody} draft={currentStep.draft} t={t}/>}
            {currentStep.draft && <div className="draft-actions"><span className="word-count"><span className={draftBody.trim().split(/\s+/).filter(Boolean).length > 230 ? "word-count-warning" : ""}>{draftBody.trim().split(/\s+/).filter(Boolean).length}</span> / 250 {t("wordCount")}</span><div className="draft-action-buttons"><span className="saved-label" aria-live="polite">{savedLabel}</span><button className="button button-ghost" onClick={() => void copyDraft()}><Copy size={15}/>{t("copyText")}</button><button className="button button-secondary" onClick={() => void handleSaveDraft()} disabled={saving}>{saving ? <LoaderCircle className="spin" size={15}/> : <Check size={15}/>} {t("saveDraft")}</button><button className="button button-primary" onClick={() => void openApprove()}><Play size={15}/>{t("prefill")}</button></div></div>}
          </div>}
          {activeTab === "agent" && <AgentPanel record={record} step={currentStep} packet={packet || currentStep?.review_packet || null} feed={feed} isRunning={isRunning} streamingUrl={streamingUrl} safetyAlert={safetyAlert} t={t} language={language} onStop={() => setConfirmStop(true)} onSubmitted={openSubmit} onRefresh={() => void refresh()} onRetry={() => void openApprove()} onPortal={() => { const url = packet?.portal_url || currentStep?.review_packet?.portal_url || (portal === "sandbox" ? `${window.location.origin}/sandbox/grievance?session=${record.id}` : currentStep?.forum.filing_url); if (url) window.open(url, "_blank", "noopener,noreferrer"); }}/>} 
          {activeTab === "timeline" && <TimelinePanel record={record} step={currentStep} clock={clock} displayDate={displayDate} t={t} language={language} onStatus={() => currentStep && void handleStatus(currentStep)} onPrepare={() => currentStep && void handlePrepareNext(currentStep)} onDownload={() => void downloadEvidence(record.id)} checkText={checkText} working={working}/>}
          <div className="work-column-bottom"><span><ShieldCheck size={14}/>{t("noSubmit")}</span><Link href={`/case/${record.id}/pack`}>Evidence pack <ArrowUpRight size={13}/></Link></div>
        </section>

        <aside className="theatre-column"><div className="theatre-top"><div><span className="eyebrow">{t("caseActivity")}</span><h2>{isRunning ? "Agent at work" : packet ? t("stopped") : t("caseInProgress")}</h2></div><span className={`theatre-status ${isRunning ? "is-live" : ""}`}><i/>{isRunning ? "LIVE" : "READY"}</span></div>
          <div className={`theatre-visual ${isRunning ? "theatre-running" : packet ? "theatre-stopped" : ""}`}><div className="theatre-glow"/><div className="theatre-device"><div className="device-topbar"><i/><i/><i/><span>{portal === "sandbox" ? "kanakpur-demo.bank" : currentStep?.forum.filing_url?.replace(/^https?:\/\//, "") || "official portal"}</span><MoreHorizontal size={14}/></div>{portal === "sandbox" && (isRunning || packet) ? <iframe title="Demo grievance form prepared by Sunwai" src={`/sandbox/grievance?session=${record.id}&agent=1${packet ? "&review=1" : ""}`} sandbox="allow-scripts allow-same-origin allow-forms" referrerPolicy="no-referrer"/> : <div className="device-placeholder"><div className="placeholder-seal"><ShieldCheck size={21}/></div><span>{isRunning ? "Preparing the official form" : packet ? t("stopped") : "The agent’s work will appear here"}</span><small>{isRunning ? "Form fields are being filled" : packet ? "Your review comes first" : "Pre-fill begins after you approve"}</small><div className="placeholder-lines"><i/><i/><i/></div></div>}</div><div className="theatre-stamp"><Stamp size={14}/><span>{packet ? t("stopped") : "YOUR REVIEW COMES FIRST"}</span></div><span className="theatre-caption">{packet ? "THE AGENT STOPPED HERE" : "DEMO PORTAL · FICTIONAL BANK"}</span></div>
          <div className="theatre-feed"><div className="feed-header"><span>ACTIVITY</span><span>{feed.length} updates</span></div><div className="feed-list" aria-live="polite" aria-relevant="additions">{feed.length ? feed.slice(-4).map((entry, index) => <div className={`feed-item feed-${entry.kind}`} key={`${entry.at}-${entry.message}-${index}`}><span className="feed-marker">{entry.kind === "warn" ? <CircleAlert size={13}/> : entry.kind === "fail" ? <X size={13}/> : entry.kind === "review" ? <Check size={13}/> : <i/>}</span><p>{entry.message}</p><time>{entry.at}</time></div>) : <div className="feed-empty"><span className="feed-empty-mark"><MessageSquareText size={16}/></span><span>The activity log appears here when the agent starts.</span></div>}</div></div>
          <button className="theatre-open-link" onClick={() => currentStep?.forum.filing_url && window.open(currentStep.forum.filing_url, "_blank", "noopener,noreferrer")}>{t("openPortal")} <ArrowUpRight size={13}/></button>
        </aside>
      </div>
      {confirmStop && <ConfirmDialog title={t("stopAgent")} body={t("stopAgentConfirm")} onCancel={() => setConfirmStop(false)} onConfirm={() => void stopRun()} confirm={t("stopAgent")} t={t}/>}
      {modal === "approve" && preview && currentStep && <ApproveDialog t={t} preview={preview} portal={portal} setPortal={setPortal} approved={approved} setApproved={setApproved} working={working} onClose={() => setModal(null)} onStart={() => void runPrefill()} language={language}/>}
      {modal === "submitted" && <SubmittedDialog t={t} ack={ack} setAck={setAck} date={ackDate} setDate={setAckDate} max={clock?.today || "2026-10-24"} error={ackError} working={working} onClose={() => setModal(null)} onSubmit={() => void submitRecord()}/>}
      <nav className="mobile-bottom-tabs" aria-label="Case sections">{(["plan", "draft", "agent", "timeline"] as Tab[]).map((tab) => <button key={tab} className={activeTab === tab ? "active" : ""} onClick={() => setActiveTab(tab)}><TabIcon tab={tab}/><span>{t(tab)}</span></button>)}</nav>
    </>}
  </main>;
}

function Fact({ label, value, masked = false }: { label: string; value: string; masked?: boolean }) { return <div className="fact-row"><span>{label}</span><strong>{masked && <LockKeyhole size={12}/>} {value}</strong></div>; }
function TabIcon({ tab }: { tab: Tab }) { return tab === "plan" ? <ArrowDownRight size={15}/> : tab === "draft" ? <FileText size={15}/> : tab === "agent" ? <Activity size={15}/> : <Clock3 size={15}/>; }
function statusLabel(status: Step["status"], t: (key: string) => string) { return status === "open" ? t("open") : status === "locked" ? t("locked") : status === "review_ready" ? t("reviewReady") : status === "submitted" ? t("submitted") : status === "due" ? t("due") : status === "waiting" ? t("waiting") : status === "done" ? t("done") : status.replace("_", " "); }
function statusIcon(status: Step["status"]) { return status === "done" || status === "submitted" ? <Check size={14}/> : status === "locked" ? <LockKeyhole size={13}/> : status === "waiting" ? <Clock3 size={14}/> : status === "blocked" ? <CircleAlert size={14}/> : <ArrowRight size={14}/>; }
function stateLabel(state: CaseRecord["state"], t: (key: string) => string) { if (state === "WAITING" || state === "SUBMITTED_BY_USER") return t("waiting"); if (state === "DUE" || state === "ESCALATION_READY") return t("due"); if (state === "REVIEW_READY") return t("reviewReady"); return state.replaceAll("_", " ").toLowerCase(); }

function StepWork({ step, record, language, t, onWrite, onPrefill, onRoute, routeLoading, onStatus, checkText, onPrepare, onPacket, working }: { step: Step; record: CaseRecord; language: Language; t: (key: string) => string; onWrite: () => void; onPrefill: () => void; onRoute: () => void; routeLoading: boolean; onStatus: () => void; checkText: string; onPrepare: () => void; onPacket: () => void; working: boolean }) {
  const action = language === "hi" ? step.action_hi : step.action; const why = language === "hi" ? step.why_hi : step.why;
  return <div className="work-panel step-work-panel"><div className="panel-topline"><div><span className="eyebrow">STEP {String(step.ordinal).padStart(2, "0")} · {step.forum.kind.toUpperCase()}</span><h2>{language === "hi" ? step.forum.name_hi : step.forum.name}</h2></div><span className={`state-pill state-${step.status}`}>{statusLabel(step.status, t)}</span></div><div className="step-explainer"><span className="explainer-pin"><span/></span><p>{action}</p><span className="explainer-why">{why}</span></div>
    {step.grievance_route && <div className="route-card"><div className="route-icon"><FileCheck2 size={16}/></div><div className="route-copy"><strong>{t("companyRouteDemo")}</strong><p>{step.grievance_route.evidence_quote}</p><span>Stored route · checked {new Date(step.grievance_route.checked_at).toLocaleDateString("en-IN", { day: "numeric", month: "short" })}</span></div><a href={step.grievance_route.grievance_form_url || "#"} target="_blank" rel="noreferrer" aria-label="Open company grievance route"><ArrowUpRight size={15}/></a></div>}
    {!step.grievance_route && step.forum.id === "company_grievance" && <button className="find-route" onClick={onRoute} disabled={routeLoading}>{routeLoading ? <LoaderCircle size={14} className="spin"/> : <RefreshCw size={14}/>} {t("findRoute")}</button>}
    <div className="date-card"><div className="date-card-heading"><span className="date-icon"><CalendarDaysMini/></span><span>{t("datesFromRules")}</span></div><div className="date-card-values"><div><span>{step.opens_at ? t("opens") : "CAN BEGIN"}</span><strong>{step.opens_at ? `${new Intl.DateTimeFormat(language === "hi" ? "hi-IN" : "en-IN", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Kolkata" }).format(new Date(`${step.opens_at}T12:00:00+05:30`))}` : step.opens_when || "After this step"}</strong></div><div className="date-rule-divider"/><div><span>{t("lastDay")}</span><strong className={step.days_until_close != null && step.days_until_close < 7 ? "date-urgent" : ""}>{step.closes_at ? new Intl.DateTimeFormat(language === "hi" ? "hi-IN" : "en-IN", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Kolkata" }).format(new Date(`${step.closes_at}T12:00:00+05:30`)) : "Not calculated yet"}</strong></div></div><div className="date-source"><span className="proof-mini"><BadgeCheck size={12}/> {step.rule?.freshness === "live" ? t("verified") : t("stored")}</span><span>{step.rule?.source_domain || "Source not available"}</span><span className="date-checked">Checked {step.rule?.fetched_at ? new Date(step.rule.fetched_at).toLocaleDateString("en-IN", { day: "numeric", month: "short" }) : "in demo"}</span></div></div>
    {step.needs_verification && <div className="official-check-note"><TriangleAlert size={14}/><span>{t("needsCheck")}</span><a href={step.forum.official_url || "#"} target="_blank" rel="noreferrer">Official source <ArrowUpRight size={12}/></a></div>}
    {step.status === "open" && <div className="step-main-actions"><button className="button button-secondary" onClick={onWrite} disabled={working}>{working ? <LoaderCircle className="spin" size={15}/> : <FileText size={15}/>} {t("writeComplaint")}</button><button className="button button-primary" onClick={onPrefill} disabled={working}><Play size={15}/>{t("prefill")}</button></div>}
    {step.status === "review_ready" && <div className="step-main-actions"><button className="button button-secondary" onClick={onPacket}><FileCheck2 size={15}/>{t("reviewReady")}</button><button className="button button-primary" onClick={() => window.open(step.review_packet?.portal_url || step.forum.filing_url || "#", "_blank", "noopener,noreferrer")}><ExternalLink size={15}/>{t("openPortal")}</button></div>}
    {step.status === "blocked" && <div className="handoff-inline"><CircleAlert size={17}/><span>{step.review_packet?.blocker === "otp" ? t("blockerOtp") : t("blockerGeneric")}</span><div className="step-main-actions"><button className="button button-secondary" onClick={onPrefill}><RefreshCw size={15}/>{t("retry")}</button><button className="button button-primary" onClick={onPacket}>{t("iSubmitted")}</button></div></div>}
    {step.status === "waiting" && <div className="waiting-card"><div className="waiting-card-icon"><Timer size={19}/></div><div><strong>{t("waiting")}</strong><p>We’ll show when the waiting period ends. Your acknowledgement number is <code>{step.ack_number}</code>.</p><span>Expected next step: {step.due_at ? new Intl.DateTimeFormat(language === "hi" ? "hi-IN" : "en-IN", { day: "numeric", month: "long", year: "numeric", timeZone: "Asia/Kolkata" }).format(new Date(`${step.due_at}T12:00:00+05:30`)) : "—"}</span></div><button className="button button-ghost" onClick={onStatus}><RefreshCw size={14}/>{t("checkStatus")}</button></div>}
    {step.status === "due" && <div className="due-card"><div className="due-mark"><CheckCircle2 size={18}/></div><div><strong>{t("due")}</strong><p>The demo waiting period has ended. Check the current rule and your eligibility before moving ahead.</p></div><button className="button button-primary" onClick={onPrepare}>{t("prepareNext")} <ArrowRight size={15}/></button></div>}
    {step.status === "locked" && <div className="locked-card"><LockKeyhole size={16}/><p>{step.opens_at ? `This step opens on ${new Intl.DateTimeFormat(language === "hi" ? "hi-IN" : "en-IN", { day: "numeric", month: "long", year: "numeric", timeZone: "Asia/Kolkata" }).format(new Date(`${step.opens_at}T12:00:00+05:30`))}.` : step.opens_when}</p></div>}
    {checkText && <p className="status-feedback" aria-live="polite">{checkText}</p>}
    <div className="step-evidence-foot"><div className="evidence-foot-item"><span className="evidence-foot-icon"><ShieldCheck size={15}/></span><div><strong>{t("firstCheckSource")}</strong><span>{t("sourceCanChange")}</span></div></div><div className="evidence-foot-item"><span className="evidence-foot-icon"><MousePointer2 size={15}/></span><div><strong>{t("thenYouDecide")}</strong><span>{t("nothingSubmitted")}</span></div></div></div>
  </div>;
}
function CalendarDaysMini() { return <Clock3 size={16}/>; }

function DraftEditor({ subject, body, onSubject, onBody, draft, t }: { subject: string; body: string; onSubject: (value: string) => void; onBody: (value: string) => void; draft: Draft; t: (key: string) => string }) {
  return <><div className="draft-form"><label><span>{t("subject")}</span><input value={subject} onChange={(event) => onSubject(event.target.value)}/></label><label><span>{t("complaintBody")}</span><textarea value={body} onChange={(event) => onBody(event.target.value)} rows={13}/></label><div className="placeholder-help"><span className="eyebrow">TO COMPLETE</span><div>{draft.placeholders_to_fill.map((placeholder) => <span className="placeholder-chip" key={placeholder}>{placeholder.replace(/[\[\]]/g, "")}</span>)}</div></div><div className="attachments-check"><span className="eyebrow">{t("attachmentChecklist")}</span>{draft.attachments_to_mention.map((item) => <label key={item}><input type="checkbox"/><span>{item}</span></label>)}</div>{!draft.safety.ok && <div className="safety-notice"><ShieldAlert size={16}/><div><strong>{t("safetyNotice")}</strong>{draft.safety.issues.map((issue) => <p key={issue.quote}>“{issue.quote}” — {issue.fix}</p>)}</div></div>}</div></>;
}

function AgentPanel({ record, step, packet, feed, isRunning, streamingUrl, safetyAlert, t, language, onStop, onSubmitted, onRefresh, onRetry, onPortal }: { record: CaseRecord; step: Step | null; packet: ReviewPacket | null; feed: FeedEntry[]; isRunning: boolean; streamingUrl: string | null; safetyAlert: { reason: string; evidence: string } | null; t: (key: string) => string; language: Language; onStop: () => void; onSubmitted: () => void; onRefresh: () => void; onRetry: () => void; onPortal: () => void }) {
  const [scrolledUp, setScrolledUp] = useState(false); const [copyState, setCopyState] = useState("");
  const copyFields = async () => { const text = packet?.fields.filter((field) => field.value).map((field) => `${field.label}: ${field.value}`).join("\n") || step?.draft?.body || ""; await navigator.clipboard?.writeText(text); setCopyState("Copied"); window.setTimeout(() => setCopyState(""), 1600); };
  return <div className="agent-panel">
    <div className="panel-topline agent-heading"><div><span className="eyebrow">STEP {String(step?.ordinal || 1).padStart(2, "0")} · HUMAN REVIEW REQUIRED</span><h2>{t("theatreTitle")}</h2></div><span className={`run-pill ${isRunning ? "run-live" : packet ? "run-complete" : ""}`}><i/>{isRunning ? "RUNNING" : packet ? "STOPPED SAFELY" : "READY"}</span></div>
    <div className={`agent-live-frame ${isRunning ? "agent-active" : ""}`}><div className="live-frame-header"><div><span className="live-frame-dot"/><span>{packet?.portal_url?.replace(/^https?:\/\//, "") || step?.forum.filing_url?.replace(/^https?:\/\//, "") || "kanakpur-demo.bank"}</span></div><span>{isRunning ? <><span className="live-time-dot"/> LIVE VIEW</> : packet ? "REVIEW PAGE" : "PORTAL PREVIEW"}</span></div>{packet?.portal_mode === "sandbox" || isRunning && isMock() ? <iframe title="Kanakpur Demo Bank grievance form" src={`/sandbox/grievance?session=${record.id}&agent=1${packet ? "&review=1" : ""}`} sandbox="allow-scripts allow-same-origin allow-forms" referrerPolicy="no-referrer"/> : streamingUrl ? <iframe title="Official portal being prepared by the agent" src={streamingUrl} sandbox="allow-scripts allow-same-origin" referrerPolicy="no-referrer"/> : <div className="live-placeholder"><div className="portal-glyph"><FileText size={23}/></div><strong>{isRunning ? t("openingPortal") : packet ? t("stopped") : "Approve a pre-fill run to begin"}</strong><span>{isRunning ? "The live portal view appears here when available." : packet ? t("reviewHelp") : "The agent will stop before any final submission action."}</span></div>}</div>
    {isRunning && <div className="agent-toolbar"><span><LoaderCircle className="spin" size={14}/>{t("theatreTitle")}</span><button className="stop-button" onClick={onStop}><Ban size={14}/>{t("stopAgent")}</button></div>}
    {safetyAlert && <div className="safety-alert" role="alert"><div className="safety-alert-icon"><ShieldAlert size={19}/></div><div><strong>The agent may have tried a final action.</strong><p>{safetyAlert.reason}</p><code>{safetyAlert.evidence}</code><b>Check the portal before doing anything else.</b></div></div>}
    {packet?.blocker && <div className="blocker-card"><div className="blocker-icon"><LockKeyhole size={18}/></div><div><span className="eyebrow">HAND BACK TO YOU</span><h3>{packet.blocker === "otp" ? "This portal needs an OTP" : "Continue on the portal"}</h3><p>{packet.blocker === "otp" ? t("blockerOtp") : t("blockerGeneric")}</p><div className="blocker-actions"><button className="button button-secondary" onClick={onPortal}>{t("openPortal")} <ArrowUpRight size={14}/></button><button className="button button-ghost" onClick={() => void copyFields()}><Copy size={14}/>{copyState || t("copyFields")}</button><button className="button button-primary" onClick={onSubmitted}>{t("iSubmitted")}</button></div></div></div>}
    {feed.length > 0 && <section className="activity-section"><div className="activity-title"><div><span className="eyebrow">{t("activityHeading")}</span><h3>{t("whatHappened")}</h3></div><button className="feed-jump" onClick={() => { setScrolledUp(false); document.querySelector(".activity-list")?.scrollTo({ top: 9999, behavior: "smooth" }); }}>{t("jumpLatest")} <ArrowDownRight size={13}/></button></div><div className="activity-list" aria-live="polite" onScroll={(event) => setScrolledUp(event.currentTarget.scrollTop < event.currentTarget.scrollHeight - event.currentTarget.clientHeight - 25)}>{feed.slice(-200).map((entry, index) => <div className={`activity-row activity-${entry.kind}`} key={`${entry.message}-${index}`}><span className="activity-marker">{entry.kind === "warn" ? <CircleAlert size={13}/> : entry.kind === "fail" ? <X size={13}/> : entry.kind === "review" ? <Check size={13}/> : <i/>}</span><time>{entry.at}</time><p>{entry.message}</p></div>)}{isRunning && <div className="activity-row activity-working"><span className="activity-marker"><LoaderCircle size={13}/></span><time>NOW</time><p>Working through the form fields</p></div>}</div>{scrolledUp && <span className="scroll-up-note">You’re reading earlier activity</span>}</section>}
    {packet?.safety_flagged && <div className="safety-alert"><ShieldAlert size={19}/><div><strong>The run was stopped for a safety check.</strong><p>Review the portal before you continue.</p></div></div>}
    {packet && packet.reached_review_screen && <ReviewPacketCard packet={packet} t={t} language={language} onPortal={onPortal} onSubmitted={onSubmitted}/>}
    {!packet && !isRunning && !safetyAlert && <div className="agent-ready-card"><span className="ready-illustration"><div/><i/></span><div><strong>Pre-fill happens with your approval.</strong><p>See every field first. The agent will pause if the site asks for a login or OTP.</p><button className="button button-secondary" onClick={onRetry}><Play size={14}/>{t("prefill")}</button></div></div>}
    <div className="agent-safety-note"><ShieldCheck size={15}/><span>{t("noSubmit")}</span><span className="safety-divider"/>The agent never enters your OTP.
    </div>
  </div>;
}

function ReviewPacketCard({ packet, t, language, onPortal, onSubmitted }: { packet: ReviewPacket; t: (key: string) => string; language: Language; onPortal: () => void; onSubmitted: () => void }) {
  return <section className="review-packet"><div className="review-heading"><span className="stop-stamp"><Check size={14}/>{t("stopped")}</span><span className="eyebrow">{t("fileReviewNeeded")}</span><h2>{t("reviewTitle")}</h2><p>{t("reviewHelp")}</p></div><div className="review-proof"><div className="review-proof-icon"><ShieldCheck size={17}/></div><div><strong>{packet.stopped_before_submit ? t("stopped") : "Review before continuing"}</strong><span>{packet.notes || "Sunwai stopped before any final action."}</span></div><span className="proof-status"><Check size={12}/> SAFE STOP</span></div><div className="field-table-wrap"><table className="field-table"><thead><tr><th>{t("field")}</th><th>{t("value")}</th><th>STATUS</th></tr></thead><tbody>{packet.fields.map((field, index) => <tr key={`${field.label}-${index}`}><th scope="row">{field.label}</th><td>{field.value || <em>Not provided</em>}</td><td><span className={field.filled ? "field-status status-filled" : "field-status status-missing"}>{field.filled ? <><Check size={12}/>{t("filled")}</> : <><CircleAlert size={12}/>{t("missing")}</>}</span></td></tr>)}</tbody></table></div>{packet.fields_missing.length > 0 && <div className="missing-fields-note"><TriangleAlert size={14}/><span>Please complete: {packet.fields_missing.join(", ")}</span></div>}<div className="review-location"><span>{t("whereStopped")}</span><a href={packet.page_url || packet.portal_url} target="_blank" rel="noreferrer">{packet.page_url?.replace(/^https?:\/\//, "") || packet.portal_url.replace(/^https?:\/\//, "")} <ExternalLink size={12}/></a></div><div className="review-actions"><button className="button button-secondary" onClick={onPortal}>{t("openPortal")} <ArrowUpRight size={14}/></button><button className="button button-primary" onClick={onSubmitted}>{t("iSubmitted")}</button></div><p className="review-disclaimer"><LockKeyhole size={13}/>{t("noSubmit")}</p></section>;
}

function TimelinePanel({ record, step, clock, displayDate, t, language, onStatus, onPrepare, onDownload, checkText, working }: { record: CaseRecord; step: Step | null; clock: DemoClock | null; displayDate: (value: string | null | undefined) => string; t: (key: string) => string; language: Language; onStatus: () => void; onPrepare: () => void; onDownload: () => void; checkText: string; working: boolean }) {
  return <div className="timeline-panel"><div className="panel-topline"><div><span className="eyebrow">CASE HISTORY</span><h2>{t("timeline")}</h2></div><button className="button button-ghost" onClick={onDownload}><FileDown size={15}/>{t("downloadPack")}</button></div>{step && <div className="timeline-status-card"><div className="timeline-status-icon"><Clock3 size={18}/></div><div className="timeline-status-copy"><span className="eyebrow">CURRENT STEP · {step.status.toUpperCase()}</span><strong>{step.ack_number ? `Acknowledgement ${step.ack_number}` : step.forum.name}</strong><span>{step.submitted_at ? `Filed ${displayDate(step.submitted_at)}` : statusLabel(step.status, t)}</span>{step.due_at && <div className="timeline-wait"><div><span>{t("waiting")}</span><b>{displayDate(step.due_at)}</b></div><div className="progress-track"><i style={{ width: `${step.status === "due" ? 100 : Math.min(92, Math.max(12, ((clock?.offset_days || 0) / 30) * 100))}%` }}/></div><small>Simulated time is {clock?.simulated ? `${clock.offset_days} days ahead` : "at the start"}.</small></div>}</div>{step.status === "waiting" ? <button className="button button-secondary" onClick={onStatus} disabled={working}><RefreshCw size={14}/>{t("checkStatus")}</button> : step.status === "due" ? <button className="button button-primary" onClick={onPrepare} disabled={working}>{t("prepareNext")}</button> : null}</div>}
    {checkText && <div className="status-result"><CheckCircle2 size={15}/>{checkText}</div>}
    {step?.status_checks[0] && <div className="latest-status"><div><span className="status-dot-text">●</span><strong>{step.status_checks[0].status_text}</strong></div><p>{t("lastUpdated")} {step.status_checks[0].last_updated} · {step.status_checks[0].remarks}</p></div>}
    <div className="timeline-list"><span className="timeline-rail"/>{record.timeline.map((item, index) => <article key={`${item.at}-${index}`} className="timeline-entry"><span className={`timeline-entry-icon ${index === 0 ? "latest" : ""}`}>{index === 0 ? <Check size={13}/> : <span/>}</span><div><span className="timeline-time">{new Date(item.at).toLocaleString(language === "hi" ? "hi-IN" : "en-IN", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}</span><strong>{language === "hi" ? item.title_hi : item.title}</strong>{item.detail && <p>{item.detail}</p>}</div></article>)}</div><div className="timeline-bottom-note"><Info size={14}/>Timeline dates use the demo clock when the simulated label is visible.</div></div>;
}

function ApproveDialog({ t, preview, portal, setPortal, approved, setApproved, working, onClose, onStart, language }: { t: (key: string) => string; preview: Awaited<ReturnType<typeof previewPrefill>>; portal: "sandbox" | "live"; setPortal: (portal: "sandbox" | "live") => void; approved: boolean; setApproved: (approved: boolean) => void; working: boolean; onClose: () => void; onStart: () => void; language: Language }) {
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="modal approve-modal" role="dialog" aria-modal="true" aria-labelledby="approve-heading"><div className="modal-header"><div><span className="eyebrow">YOUR PERMISSION · REQUIRED</span><h2 id="approve-heading">{t("approveTitle")}</h2></div><button className="icon-button" onClick={onClose} aria-label={t("close")}><X size={18}/></button></div><p className="modal-intro">{t("approveIntro")}</p><div className="portal-choice"><span className="eyebrow">{t("portalMode")}</span><div className="portal-segment"><button className={portal === "sandbox" ? "selected" : ""} onClick={() => setPortal("sandbox")}><span className="portal-seal">D</span><span><strong>{t("sandbox")}</strong><small>kanakpur-demo.bank</small></span>{portal === "sandbox" && <Check size={15}/>}</button><button className={portal === "live" ? "selected" : ""} onClick={() => setPortal("live")}><span className="portal-seal portal-live">↗</span><span><strong>{t("official")}</strong><small>{preview.portal_url.replace(/^https?:\/\//, "")}</small></span>{portal === "live" && <Check size={15}/>}</button></div></div><div className="preview-field-list"><div className="preview-title"><span className="eyebrow">{t("fieldPreview")}</span><span>{preview.field_map.length} fields</span></div>{preview.field_map.map((field) => <div className="preview-field" key={field.label}><span>{field.label}</span><strong>{field.value || "Not provided"}</strong><small>{field.source || "—"}</small></div>)}</div><div className="preview-excerpt"><span className="eyebrow">{t("excerpt")}</span><p>{preview.draft_excerpt || "No draft available yet."}</p></div><ul className="agent-promises"><li><Check size={13}/>{t("promiseStop")}</li><li><Check size={13}/>{t("promiseSubmit")}</li><li><LockKeyhole size={13}/>{t("promiseOtp")}</li></ul><div className="modal-warning"><Info size={15}/><span>{t("warning")}</span></div><label className="approval-check"><input type="checkbox" checked={approved} onChange={(event) => setApproved(event.target.checked)}/><span>{t("confirmDetails")}</span></label><div className="modal-actions"><button className="button button-ghost" onClick={onClose}>{t("cancel")}</button><button className="button button-primary" onClick={onStart} disabled={!approved || working}>{working ? <LoaderCircle className="spin" size={15}/> : <Play size={14}/>} {t("startPrefill")}</button></div></section></div>;
}

function SubmittedDialog({ t, ack, setAck, date, setDate, max, error, working, onClose, onSubmit }: { t: (key: string) => string; ack: string; setAck: (value: string) => void; date: string; setDate: (value: string) => void; max: string; error: string; working: boolean; onClose: () => void; onSubmit: () => void }) {
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="modal submitted-modal" role="dialog" aria-modal="true" aria-labelledby="submitted-heading"><div className="submitted-modal-icon"><Stamp size={20}/></div><div className="modal-header"><div><span className="eyebrow">A FILING YOU MADE</span><h2 id="submitted-heading">{t("ackTitle")}</h2></div><button className="icon-button" onClick={onClose} aria-label={t("close")}><X size={18}/></button></div><p className="modal-intro">{t("ackHelp")}</p><label className="modal-field"><span>{t("ack")}</span><input autoFocus value={ack} onChange={(event) => setAck(event.target.value)} maxLength={64} placeholder="e.g. CMS/2026/00184" autoComplete="off"/></label><label className="modal-field"><span>{t("ackDate")}</span><input type="date" value={date} max={max} onChange={(event) => setDate(event.target.value)}/></label>{error && <p className="inline-error" role="alert">{error}</p>}<div className="modal-actions"><button className="button button-ghost" onClick={onClose}>{t("cancel")}</button><button className="button button-primary" onClick={onSubmit} disabled={working}>{working ? <LoaderCircle className="spin" size={15}/> : <Check size={15}/>} {t("recordFiled")}</button></div><p className="ack-note"><LockKeyhole size={13}/>Only you can record a filed complaint here.</p></section></div>;
}

function ConfirmDialog({ title, body, onCancel, onConfirm, confirm, t }: { title: string; body: string; onCancel: () => void; onConfirm: () => void; confirm: string; t: (key: string) => string }) { return <div className="modal-backdrop" role="presentation"><section className="modal small-modal" role="dialog" aria-modal="true"><div className="modal-header"><h2>{title}</h2><button className="icon-button" onClick={onCancel} aria-label={t("close")}><X size={18}/></button></div><p className="modal-intro">{body}</p><div className="modal-actions"><button className="button button-ghost" onClick={onCancel}>{t("cancel")}</button><button className="button button-danger" onClick={onConfirm}>{confirm}</button></div></section></div>; }
